import { useForm, SubmitHandler } from 'react-hook-form';

export type LoginInputs = { email: string; password: string };

export function LoginForm({ onSubmit }: { onSubmit: (data: LoginInputs) => void }) {
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginInputs>();

  const submit: SubmitHandler<LoginInputs> = (data) => {
    onSubmit(data);
  };

  return (
    <form onSubmit={handleSubmit(submit)}>
      <input placeholder="email" {...register('email', { required: 'Email is required' })} />
      {errors.email ? <p role="alert">{errors.email.message}</p> : null}

      <input placeholder="password" type="password" {...register('password', { required: 'Password is required' })} />
      {errors.password ? <p role="alert">{errors.password.message}</p> : null}

      <button type="submit">Sign in</button>
    </form>
  );
}
